# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step6_posthoc_LCMS_annotation.R
# 5A Step 6: frozen post-hoc LC-MS/MS annotation and class-level concordance
local({
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225';OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225');S6<-file.path(OUT,'step6_posthoc_LCMS_annotation');dir.create(S6,recursive=TRUE,showWarnings=FALSE)
map<-fread(file.path(OUT,'step3_modules','all_eligible_features_module_membership_with_ion_families.csv'));map<-map[module!='grey'];annfile<-'/home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/visualization_2C/20260908_100345/manuscript_figure/Supplementary_Table_S1_complete_matches.csv';ann<-fread(annfile);need<-c('feature_index','msi_mz','lc_row','entity_key','metabolite','formula','lc_ID','lc_mz','retention_time_min','declared_lc_adduct','predicted_msi_ion','predicted_ion_family','absolute_mass_difference_da','mass_difference_ppm','match_path_category','monoisotopic_core','fragmentation_score','MS2_fragment_supported','annotation_mass_error_ppm','HMDB','PubChem','KEGG');stopifnot(all(need%in%names(ann)))
ann<-merge(ann,map[,.(feature_index,representative_feature,module,is_representative,ion_family_size)],by='feature_index',all=FALSE);ann[,evidence_tier:=fifelse(MS2_fragment_supported==TRUE&monoisotopic_core==TRUE,'A_core_fragment_supported',fifelse(MS2_fragment_supported==TRUE,'B_fragment_supported_noncore',fifelse(monoisotopic_core==TRUE,'C_core_mass_match','D_other_mass_match')))];setorder(ann,module,representative_feature,evidence_tier,absolute_mass_difference_da,-fragmentation_score);fwrite(ann,file.path(S6,'all_LCMS_candidates_mapped_to_frozen_modules.csv'))
# One best row per representative family and LC entity; labels remain putative.
best<-ann[, .SD[1],by=.(module,representative_feature,lc_row)];best[,n_candidate_entities_for_representative:=uniqueN(lc_row),by=.(module,representative_feature)];fwrite(best[,c('module','representative_feature','feature_index','msi_mz','ion_family_size','lc_row','entity_key','metabolite','formula','lc_ID','lc_mz','retention_time_min','declared_lc_adduct','predicted_msi_ion','absolute_mass_difference_da','mass_difference_ppm','monoisotopic_core','fragmentation_score','MS2_fragment_supported','annotation_mass_error_ppm','HMDB','PubChem','KEGG','evidence_tier','n_candidate_entities_for_representative'),with=FALSE],file.path(S6,'deduplicated_module_annotation_candidates.csv'))
mods<-sort(unique(map$module));summ<-rbindlist(lapply(mods,function(mm){mf<-unique(map[module==mm,representative_feature]);x<-best[module==mm];data.table(module=mm,n_representative_families=length(mf),n_families_with_any_LCMS_candidate=uniqueN(x$representative_feature),fraction_families_annotated=uniqueN(x$representative_feature)/length(mf),n_families_with_fragment_supported=uniqueN(x[MS2_fragment_supported==TRUE,representative_feature]),n_core_fragment_supported_pairs=nrow(x[MS2_fragment_supported==TRUE&monoisotopic_core==TRUE]),n_unique_candidate_entities=uniqueN(x$lc_row),n_unique_candidate_metabolite_names=uniqueN(x[!is.na(metabolite)&metabolite!='',metabolite]),n_unique_KEGG_ids=uniqueN(x[!is.na(KEGG)&KEGG!='',KEGG]))}));
# Class-level LC-MSI concordance is post-hoc and uses only annotation-linked families. No subject pairing is assumed.
lc_cols<-grep('^LC_reported_log2__',names(best),value=TRUE);msi_cols<-grep('^MSI_primary__',names(best),value=TRUE);zrow<-function(M){t(apply(M,1,function(v){s<-sd(v,na.rm=TRUE);if(!is.finite(s)||s<1e-10)rep(NA_real_,length(v))else (v-mean(v,na.rm=TRUE))/s}))};lc_class<-c(rep('Cushing',2),rep('GH',3),'NF-GH',rep('NF-ACTH',3),rep('NF-GnH',3));msi_class<-c(rep('Cushing',2),rep('GH',3),'NF-ACTH','NF-GH',rep('NF-GnH',3));classes<-c('Cushing','GH','NF-GH','NF-ACTH','NF-GnH');con<-list();profiles<-list()
for(mm in mods){x<-best[module==mm];xlc<-x[!duplicated(lc_row)];xmsi<-x[!duplicated(representative_feature)];L<-as.matrix(xlc[,..lc_cols]);I<-as.matrix(xmsi[,..msi_cols]);storage.mode(L)<-'double';storage.mode(I)<-'double';lp<-if(nrow(L))colMeans(zrow(L),na.rm=TRUE)else rep(NA_real_,length(lc_cols));ip<-if(nrow(I))colMeans(zrow(I),na.rm=TRUE)else rep(NA_real_,length(msi_cols));lpc<-vapply(classes,function(g)mean(lp[lc_class==g],na.rm=TRUE),numeric(1));ipc<-vapply(classes,function(g)mean(ip[msi_class==g],na.rm=TRUE),numeric(1));rho<-if(sum(is.finite(lpc)&is.finite(ipc))>=4)cor(lpc,ipc,method='spearman',use='complete.obs')else NA_real_;con[[mm]]<-data.table(module=mm,n_LC_entities=nrow(L),n_MSI_representative_families=nrow(I),class_profile_spearman=as.numeric(rho));profiles[[mm]]<-data.table(module=mm,class=classes,LC_module_z=lpc,MSI_module_z=ipc)}
con<-rbindlist(con);summ<-merge(summ,con,by='module',all.x=TRUE);fwrite(summ,file.path(S6,'module_LCMS_annotation_summary.csv'));fwrite(rbindlist(profiles),file.path(S6,'module_class_profiles_LCMS_vs_MSI.csv'))
p1<-ggplot(summ,aes(x=reorder(module,fraction_families_annotated),y=fraction_families_annotated))+geom_col(fill='#8DA0CB')+coord_flip()+labs(x=NULL,y='Fraction of representative families',title='Post-hoc LC-MS/MS candidate coverage')+theme_bw(base_size=11);p2<-ggplot(summ,aes(x=reorder(module,class_profile_spearman),y=class_profile_spearman))+geom_col(fill='#FC8D62')+geom_hline(yintercept=0,lty=2)+coord_flip()+labs(x=NULL,y='Spearman rho across 5 classes',title='LC-MSI class-profile concordance')+theme_bw(base_size=11);ggsave(file.path(S6,'step6_LCMS_annotation_summary.pdf'),p1/p2,width=10,height=9)
saveRDS(list(summary=summ,profiles=rbindlist(profiles),annotation_file=annfile,annotation_md5=tools::md5sum(annfile),principle='post-hoc only: no LC field was permitted to change MSI eligibility, ion-family collapse, network, modules, scores, or spatial metrics'),file.path(S6,'LCMS_posthoc_annotation_results.rds'))
writeLines(c('LC-MS/MS is introduced only after MSI modules and spatial metrics are frozen.','All names are putative candidates inherited from the frozen mass/MS2 correspondence table; multiple candidates may map to one MSI ion family.','Evidence tier A requires both monoisotopic-core status and fragment support, but is still not presented as an independent definitive identification.','Class-profile correlation compares five class averages and is descriptive. The LC and MSI subjects are not paired.','No LC result changes any MSI analysis result.'),file.path(S6,'README.txt'))
cat('STEP6_COMPLETE\n');print(summ[order(-n_families_with_fragment_supported),.(module,n_representative_families,n_families_with_any_LCMS_candidate,n_families_with_fragment_supported,n_core_fragment_supported_pairs,n_unique_candidate_metabolite_names,class_profile_spearman)]);cat('OUT=',S6,'\n')
})
